)
INSERT INTO public.catalog_translations (entity_type, entity_id, locale, name, is_manual)
SELECT 'product', i.id, l.key, l.value, false
FROM ins i CROSS JOIN LATERAL jsonb_each_text(
  (SELECT tr FROM data d WHERE d.name = i.name)
) l;